# =============================================================================
# analysis.R
# Workshop 3: Facial Expression Analysis of a Video Commercial with Affectiva AFFDEX
# and the Lab Webcam in iMotions Lab 11.1, analysis session
# Martin's Family Clothing Consumer Behavior Research Laboratory, JSU
#
# SIMULATED DATA. Every number this script reads was generated by
# make_simulated_data.py (the seed is printed at the top of the output). No viewer was
# recorded. The design follows the structure of the lab's library study "Nike Campaign Ad
# Evaluation" (a 60 s Baseline, a 60 s commercial, a 15 s Recovery, a short questionnaire,
# the respondent camera recorded for AFFDEX) and nothing else about it. The content of the
# commercial is not described because it is not known here.
#
# Design: ONE viewing by 32 respondents (V01 to V32). The webcam video was post processed with
# Affectiva AFFDEX and then run through the FEA thresholding R Notebook at its default
# thresholds (Emotion 50, Valence +50 and -50, Action Units 50). The commercial carries a
# binning stimulus annotation that cuts it into six 10 s bins (Bin_01 to Bin_06). The FEA
# Metrics Export gives, per respondent and time interval (Stimulus or Annotation), the percent
# of time an expression was present and the number of segments.
#
# HEADER LAYOUT: modeled on the manual's description of the FEA Metrics Export. The manuals
# print no header row, so the column names are a clear choice and must be verified on the lab
# machine. Section 1 below is the one place where the export headers are renamed.
#
# What the script does, in order:
#   0. Load packages and set paths and the figure theme
#   1. Read the simulated FEA Metrics Export (three threshold runs), the survey, and the log
#   2. Clean: apply the exclusion rule (Data quality below 80 percent, the lab's own rule)
#   3. Descriptive table by expression and interval (mean, SD, median, viewers with the
#      expression present, segments); Engagement as a raw mean
#   4. H1: Joy Percent of time present, Commercial versus Baseline (paired). Primary test: the
#      Wilcoxon signed rank test (the variable is zero inflated); paired t test and d_z beside it
#      4b. Sensitivity: the same test at thresholds of 25 and 75
#   5. H2: Joy across the six bins: linear mixed model (bin as a factor, random intercept per
#      respondent), the proportion of viewers with Joy present per bin (the quantity the FEA
#      thresholding Aggregation shows), and a Friedman test as the nonparametric check
#   6. H3: Positive Valence Percent of time present during the commercial and Ad_liking_1to7
#      (Pearson and Spearman)
#   7. Other expressions by bin (descriptive)
#   8. Assumption checks (plots saved to figures/)
#   9. Three report figures saved as PNG, 1400 px wide, 150 dpi
#
# Sign convention: the H1 difference is Commercial MINUS Baseline. A positive difference means
# more time with Joy present during the commercial.
#
# How to run (either way works):
#   a) In RStudio: open this file, set the working directory to the folder that holds the CSV
#      files (Session > Set Working Directory > To Source File Location), then Source.
#   b) From a terminal, inside the data folder:  Rscript analysis.R
# The console output is also written to analysis_output.txt next to the data.
#
# Packages used: readr, dplyr, tidyr, ggplot2, lme4, lmerTest (p values and contrasts for the
# mixed model), effectsize (noncentral t interval for d_z and the rank biserial correlation).
# If a package is missing, run once in the console:
#   install.packages(c("readr", "dplyr", "tidyr", "ggplot2", "lme4", "lmerTest", "effectsize"))
# =============================================================================

# ---- 0. Setup ---------------------------------------------------------------
suppressPackageStartupMessages({
  library(readr)
  library(dplyr)
  library(tidyr)
  library(ggplot2)
  library(lme4)
  library(lmerTest)
})
has_effectsize <- requireNamespace("effectsize", quietly = TRUE)

script_dir <- tryCatch({
  args <- commandArgs(trailingOnly = FALSE)
  f <- sub("^--file=", "", args[grep("^--file=", args)])
  if (length(f) == 1) dirname(normalizePath(f)) else getwd()
}, error = function(e) getwd())
setwd(script_dir)
fig_dir <- file.path(script_dir, "figures")
dir.create(fig_dir, showWarnings = FALSE)

output_file <- file.path(script_dir, "analysis_output.txt")
sink(output_file, split = TRUE)
data_seed <- as.integer(sub(".*seed ([0-9]+).*", "\\1", readLines("SIMULATED_fea_metrics.csv", n = 1)))
cat("SIMULATED facial expression analysis, run on", format(Sys.time(), "%Y-%m-%d %H:%M"), "\n")
cat("R", R.version$major, ".", R.version$minor, "; lme4 ", as.character(packageVersion("lme4")),
    "; lmerTest ", as.character(packageVersion("lmerTest")),
    "; effectsize available: ", has_effectsize, "; data seed ", data_seed, "\n\n", sep = "")

# Palette: navy (the commercial), gray (baseline and other intervals), one accent for the means.
col_navy   <- "#1F3864"
col_gray   <- "#8C8C8C"
col_accent <- "#A6561A"
col_tint   <- "#C9D3E6"

theme_fea <- function(base_size = 13) {
  theme_minimal(base_size = base_size) +
    theme(panel.grid.minor = element_blank(),
          panel.grid.major.x = element_blank(),
          panel.grid.major.y = element_line(color = "#E3E3E3", linewidth = 0.4),
          axis.line.x = element_line(color = "#B0B0B0", linewidth = 0.4),
          plot.title = element_text(face = "bold", size = base_size + 2),
          plot.subtitle = element_text(color = "#555555"),
          plot.caption = element_text(color = "#777777", size = base_size - 3, hjust = 0),
          legend.position = "top",
          legend.title = element_blank(),
          plot.background = element_rect(fill = "white", color = NA))
}
save_fig <- function(plot, name, height_px = 900) {
  # 1400 px wide at 150 dpi = 9.33 in wide
  ggsave(file.path(fig_dir, name), plot, width = 1400 / 150, height = height_px / 150, dpi = 150, bg = "white")
  cat("saved figure:", file.path("figures", name), "\n")
}
fp <- function(p) ifelse(p < .001, "p < .001", paste0("p = ", sub("^0", "", sprintf("%.3f", p))))
# p value for the output file: five decimals, scientific notation below 0.0001 so no p prints as 0.00000
pf <- function(p) ifelse(p < 0.0001, sprintf("%.2e", p), sprintf("%.5f", p))
rr <- function(x) sub("^(-?)0\\.", "\\1.", sprintf("%.2f", x))      # no leading zero, for figure text

expr_levels  <- c("Joy", "Surprise", "Brow Furrow", "Positive Valence", "Negative Valence", "Engagement")
stim_levels  <- c("Baseline", "Commercial", "Recovery")
bin_levels   <- sprintf("Bin_%02d", 1:6)
int_levels   <- c(stim_levels, bin_levels)
dq_rule      <- 80      # the lab's own exclusion rule (the manuals state no minimum)

# ---- 1. Read the files ------------------------------------------------------
# Line 1 of every file is a "# SIMULATED" comment, so comment = "#" skips it. NA is written as the
# text NA (Engagement has no thresholded metrics; its raw mean is in its own column).
read_fea <- function(f) {
  read_csv(f, comment = "#", na = c("NA", ""), show_col_types = FALSE,
           col_types = cols(Threshold = col_character()))
}
fea_raw    <- read_fea("SIMULATED_fea_metrics.csv")              # default thresholds (50, +50 / -50)
fea25_raw  <- read_fea("SIMULATED_fea_metrics_threshold25.csv")  # notebook run again at a batch threshold of 25
fea75_raw  <- read_fea("SIMULATED_fea_metrics_threshold75.csv")  # and of 75
survey     <- read_csv("SIMULATED_fea_survey.csv", comment = "#", show_col_types = FALSE)
session    <- read_csv("SIMULATED_fea_session_log.csv", comment = "#", show_col_types = FALSE)

cat("---- 1. Files read ----\n")
cat("FEA metrics rows:", nrow(fea_raw), " respondents:", n_distinct(fea_raw$`Respondent Name`),
    " intervals:", paste(unique(fea_raw$`Interval label`), collapse = ", "), "\n")
cat("Expressions:", paste(unique(fea_raw$Expression), collapse = ", "), "\n")
cat("Thresholds in the default file:", paste(unique(fea_raw$Threshold), collapse = ", "),
    "; in the two sensitivity files:", paste(unique(fea25_raw$Threshold), collapse = ", "), "and",
    paste(unique(fea75_raw$Threshold), collapse = ", "), "\n")
cat("Survey rows:", nrow(survey), "  Session log rows:", nrow(session), "\n\n")

# Rename the export headers to short R friendly names. Keep this block as the one place where
# the mapping from export header to variable lives.
rename_fea <- function(d) {
  d %>%
    rename(respondent = `Respondent Name`,
           itype      = `Interval type`,
           interval   = `Interval label`,
           dur_s      = `Interval duration (s)`,
           expr       = Expression,
           threshold  = Threshold,
           pct        = `Percent of time present`,
           nseg       = `Number of segments`,
           raw_mean   = `Mean raw score (0-100)`,
           dq         = `Data quality (%)`) %>%
    mutate(expr = factor(expr, levels = expr_levels),
           interval = factor(interval, levels = int_levels))
}
fea   <- rename_fea(fea_raw)
fea25 <- rename_fea(fea25_raw)
fea75 <- rename_fea(fea75_raw)
survey <- survey %>% rename(respondent = `Respondent Name`, gender = Gender, age = Age,
                            liking = Ad_liking_1to7, attitude = Brand_attitude_1to7, share = Would_share_Yes_No)

# ---- 2. Clean ---------------------------------------------------------------
# Exclusion rule, fixed before data collection: Data quality below 80 percent. Data quality is the
# percentage of frames successfully analyzed (Quality Metrics after post processing); it is NOT an
# indicator of overall accuracy. The manuals state no minimum, so 80 percent is the lab's own rule.
resp_dq <- fea %>% distinct(respondent, dq)
excluded <- resp_dq %>% filter(dq < dq_rule)
cat("---- 2. Cleaning ----\n")
cat(sprintf("Data quality (percentage of frames successfully analyzed, after post processing): all %d respondents M = %.1f, SD = %.2f, range %.1f to %.1f\n",
            nrow(resp_dq), mean(resp_dq$dq), sd(resp_dq$dq), min(resp_dq$dq), max(resp_dq$dq)))
kept_dq <- resp_dq %>% filter(dq >= dq_rule)
cat(sprintf("Kept respondents (Data quality >= %d): n = %d, M = %.1f, SD = %.2f, range %.1f to %.1f\n",
            dq_rule, nrow(kept_dq), mean(kept_dq$dq), sd(kept_dq$dq), min(kept_dq$dq), max(kept_dq$dq)))
cat(sprintf("Excluded (Data quality < %d percent, the lab's own rule; the manuals state no minimum):\n", dq_rule))
print(as.data.frame(excluded))
cat("Session log says for these respondents:\n")
print(as.data.frame(session %>% filter(`Respondent Name` %in% excluded$respondent) %>%
                      select(`Respondent Name`, `Session Date`, Glasses, `Face detection percent`, `Data complete`)))
for (i in seq_len(nrow(excluded))) {
  cat("Lighting note:", session$`Lighting note`[session$`Respondent Name` == excluded$respondent[i]],
      "\nDecision note:", session$`Decision note`[session$`Respondent Name` == excluded$respondent[i]], "\n")
}
cat(sprintf("Session log Face detection percent equals Data quality (%%) in the metrics file for all respondents: %s\n",
            all(abs(session$`Face detection percent`[match(resp_dq$respondent, session$`Respondent Name`)] - resp_dq$dq) < 1e-9)))
cat("Lowest Data quality among kept respondents:", sprintf("%.1f", min(kept_dq$dq)),
    "(", kept_dq$respondent[which.min(kept_dq$dq)], ")\n")

keep_ids <- kept_dq$respondent
clean <- function(d) d %>% filter(respondent %in% keep_ids)
fea_c <- clean(fea); fea25_c <- clean(fea25); fea75_c <- clean(fea75)
survey_c <- survey %>% filter(respondent %in% keep_ids)
cat("Respondents kept:", length(keep_ids), "\n")
cat(sprintf("Kept respondents by gender: F = %d, M = %d; age M = %.1f, SD = %.1f, range %d to %d\n",
            sum(survey_c$gender == "F"), sum(survey_c$gender == "M"), mean(survey_c$age), sd(survey_c$age),
            min(survey_c$age), max(survey_c$age)))
cat("Session dates:", paste(range(session$`Session Date`), collapse = " to "), "\n\n")

# ---- 3. Descriptive table by expression and interval -------------------------
# Percent of time present and Number of segments: all kept respondents (zeros included).
# Viewers with the expression present = respondents whose Percent of time present is above 0 in
# the interval (equivalently, at least one segment). Engagement is a raw mean score (0 to 100).
desc_t <- fea_c %>% filter(expr != "Engagement") %>%
  group_by(expr, itype, interval) %>%
  summarise(n = n(),
            mean_pct = mean(pct), sd_pct = sd(pct), median_pct = median(pct),
            n_present = sum(pct > 0), pct_present = 100 * mean(pct > 0),
            mean_segments = mean(nseg), sd_segments = sd(nseg),
            mean_raw_score = NA_real_, sd_raw_score = NA_real_, .groups = "drop")
desc_e <- fea_c %>% filter(expr == "Engagement") %>%
  group_by(expr, itype, interval) %>%
  summarise(n = sum(!is.na(raw_mean)), mean_pct = NA_real_, sd_pct = NA_real_, median_pct = NA_real_,
            n_present = NA_integer_, pct_present = NA_real_, mean_segments = NA_real_, sd_segments = NA_real_,
            mean_raw_score = mean(raw_mean, na.rm = TRUE), sd_raw_score = sd(raw_mean, na.rm = TRUE), .groups = "drop")
desc <- bind_rows(desc_t, desc_e) %>%
  mutate(across(where(is.double), ~ round(.x, 2))) %>%
  arrange(expr, interval) %>%
  rename(expression = expr, interval_type = itype)
cat("---- 3. Descriptive table by expression and interval (kept respondents, default thresholds) ----\n")
cat("mean_pct = mean Percent of time present; n_present = viewers with the expression present (pct > 0);\n")
cat("mean_segments = mean Number of segments; Engagement is a raw mean score, not a thresholded metric.\n")
print(as.data.frame(desc %>% filter(expression != "Engagement") %>%
                      select(expression, interval, n, mean_pct, sd_pct, median_pct, n_present, pct_present, mean_segments, sd_segments)),
      row.names = FALSE)
cat("\nEngagement (mean raw score, 0 to 100):\n")
print(as.data.frame(desc %>% filter(expression == "Engagement") %>% select(expression, interval, n, mean_raw_score, sd_raw_score)),
      row.names = FALSE)
write_csv(desc, "SIMULATED_descriptives_by_interval.csv")
cat("written: SIMULATED_descriptives_by_interval.csv\n\n")

# Consistency checks the students can repeat: the bins tile the commercial.
bins_all <- fea_c %>% filter(expr == "Joy", itype == "Annotation") %>% select(respondent, interval, pct, nseg)
comm_all <- fea_c %>% filter(expr == "Joy", interval == "Commercial") %>% select(respondent, pct_c = pct, nseg_c = nseg)
chk <- bins_all %>% group_by(respondent) %>% summarise(mean_bins = mean(pct), sum_seg = sum(nseg), .groups = "drop") %>%
  inner_join(comm_all, by = "respondent")
cat(sprintf("Check: Joy Percent of time present in Commercial equals the mean of the six bins (largest absolute gap %.2f percentage points, rounding only)\n",
            max(abs(chk$pct_c - chk$mean_bins))))
cat(sprintf("Check: Joy Number of segments in Commercial versus the sum over the six bins (a segment that crosses a bin boundary counts in both bins): Commercial M = %.2f, sum of bins M = %.2f\n\n",
            mean(chk$nseg_c), mean(chk$sum_seg)))

# Realized versus planned: any one sample of 30 drifts from its model.
mp <- function(e, i) desc$mean_pct[desc$expression == e & desc$interval == i]
joy_w0 <- fea_c %>% filter(expr == "Joy", interval == "Baseline")
cat("Realized versus planned (generator assumptions in make_simulated_data.py):\n")
cat(sprintf("  Joy Percent of time present: Baseline %.1f (planned about 2), Commercial %.1f (about 11), Recovery %.1f (about 4)\n",
            mp("Joy", "Baseline"), mp("Joy", "Commercial"), mp("Joy", "Recovery")))
cat(sprintf("  Joy at Baseline: %d of %d viewers had 0 (planned: most viewers 0)\n", sum(joy_w0$pct == 0), nrow(joy_w0)))
cat(sprintf("  Joy by bin: %s (planned 5, 6, 8, 8, 24, 15)\n",
            paste(sprintf("%.1f", sapply(bin_levels, function(b) mp("Joy", b))), collapse = ", ")))
cat(sprintf("  Surprise by bin: %s (planned peak in Bin_03)\n",
            paste(sprintf("%.1f", sapply(bin_levels, function(b) mp("Surprise", b))), collapse = ", ")))
cat(sprintf("  Brow Furrow by bin: %s (planned small and flat, 2 to 5)\n",
            paste(sprintf("%.1f", sapply(bin_levels, function(b) mp("Brow Furrow", b))), collapse = ", ")))
cat(sprintf("  Negative Valence, Commercial: %.2f (planned near zero)\n\n", mp("Negative Valence", "Commercial")))

# ---- Helper: H1 comparison (Commercial minus Baseline) ----------------------
# The difference is Commercial minus Baseline, rounded to two decimals (the export has two decimals,
# so the rounding only removes floating point noise and lets tied differences tie, as they do in Excel).
# Primary test: Wilcoxon signed rank test, because Percent of time present is zero inflated and skewed.
# Beside it: the paired t test and d_z (mean difference / SD of the differences) with a noncentral t
# 95% CI, the matched pairs rank biserial correlation, and the number of viewers with any Joy.
h1_test <- function(base, comm, label, verbose = TRUE) {
  dif <- round(comm - base, 2)
  n <- length(dif)
  tt <- t.test(dif)
  dz <- mean(dif) / sd(dif)
  if (has_effectsize) {
    es <- effectsize::cohens_d(dif, ci = 0.95)
    stopifnot(abs(es$Cohens_d - dz) < 1e-8)
    dz_lo <- es$CI_low; dz_hi <- es$CI_high
  } else {
    se_d <- sqrt(1 / n + dz^2 / (2 * n)); dz_lo <- dz - 1.96 * se_d; dz_hi <- dz + 1.96 * se_d
  }
  nz <- dif[dif != 0]
  rk <- rank(abs(nz))
  w_pos <- sum(rk[nz > 0]); w_neg <- sum(rk[nz < 0])
  r_rb <- (w_pos - w_neg) / (w_pos + w_neg)
  wx <- suppressWarnings(wilcox.test(dif, exact = FALSE, correct = TRUE, conf.int = TRUE))
  b_any <- sum(base > 0); c_any <- sum(comm > 0)
  disc_b <- sum(base > 0 & comm == 0); disc_c <- sum(base == 0 & comm > 0)
  mcn_p <- if (disc_b + disc_c > 0) binom.test(disc_c, disc_b + disc_c, 0.5)$p.value else NA_real_
  n_pos <- sum(dif > 0); n_neg <- sum(dif < 0); n_zero <- sum(dif == 0)
  sign_p <- if (n_pos + n_neg > 0) binom.test(n_pos, n_pos + n_neg, 0.5)$p.value else NA_real_
  sw <- shapiro.test(dif)
  if (verbose) {
    cat(sprintf("%s\n", label))
    cat(sprintf("  Baseline:   M = %.2f %%, SD = %.2f, Mdn = %.2f, n = %d\n", mean(base), sd(base), median(base), n))
    cat(sprintf("  Commercial: M = %.2f %%, SD = %.2f, Mdn = %.2f, n = %d\n", mean(comm), sd(comm), median(comm), n))
    cat(sprintf("  Viewers with any Joy present: Baseline %d of %d (%.1f%%), Commercial %d of %d (%.1f%%)\n",
                b_any, n, 100 * b_any / n, c_any, n, 100 * c_any / n))
    cat(sprintf("  Changed status: %d with Joy only at Baseline, %d with Joy only during the Commercial; exact McNemar test p = %s\n",
                disc_b, disc_c, pf(mcn_p)))
    cat(sprintf("  Mean difference (Commercial minus Baseline) = %.2f %%, SD of differences = %.2f, 95%% CI [%.2f, %.2f]\n",
                mean(dif), sd(dif), tt$conf.int[1], tt$conf.int[2]))
    cat(sprintf("  Signs of the differences: %d positive, %d negative, %d zero (dropped by the signed rank test); sign test p = %s\n",
                n_pos, n_neg, n_zero, pf(sign_p)))
    cat(sprintf("  PRIMARY: Wilcoxon signed rank V = %.0f, p = %s (n = %d nonzero differences; sum of negative ranks = %.1f)\n",
                wx$statistic, pf(wx$p.value), length(nz), w_neg))
    cat(sprintf("  Matched pairs rank biserial correlation r_rb = %.2f; Hodges-Lehmann median difference = %.2f %%, 95%% CI [%.2f, %.2f]\n",
                r_rb, wx$estimate, wx$conf.int[1], wx$conf.int[2]))
    cat(sprintf("  Paired t(%d) = %.2f, p = %s\n", as.integer(tt$parameter), tt$statistic, pf(tt$p.value)))
    cat(sprintf("  Cohen's d_z = %.2f, 95%% CI [%.2f, %.2f]  (%s)\n", dz, dz_lo, dz_hi,
                if (has_effectsize) "noncentral t (effectsize)" else "large sample approximation"))
    cat(sprintf("  Shapiro Wilk on the differences: W = %.3f, p = %s\n\n", sw$statistic, pf(sw$p.value)))
  }
  invisible(list(label = label, n = n, m_b = mean(base), sd_b = sd(base), m_c = mean(comm), sd_c = sd(comm),
                 mdn_b = median(base), mdn_c = median(comm),
                 diff = mean(dif), sd_diff = sd(dif), ci_lo = tt$conf.int[1], ci_hi = tt$conf.int[2],
                 t = unname(tt$statistic), df = unname(tt$parameter), p = tt$p.value,
                 dz = dz, dz_lo = dz_lo, dz_hi = dz_hi, V = unname(wx$statistic), p_w = wx$p.value, n_nz = length(nz),
                 w_neg = w_neg, r_rb = r_rb, hl = unname(wx$estimate), hl_lo = wx$conf.int[1], hl_hi = wx$conf.int[2],
                 b_any = b_any, c_any = c_any, disc_b = disc_b, disc_c = disc_c, mcn_p = mcn_p,
                 n_pos = n_pos, n_neg = n_neg, n_zero = n_zero, sign_p = sign_p,
                 shapiro_p = sw$p.value, shapiro_w = unname(sw$statistic), dif = dif))
}
joy_wide <- function(d) d %>% filter(expr == "Joy", interval %in% stim_levels) %>%
  select(respondent, interval, pct) %>% pivot_wider(names_from = interval, values_from = pct) %>% arrange(respondent)

# ---- 4. H1: Joy Percent of time present, Commercial versus Baseline ----------
# H1: the share of time with Joy present is larger during the commercial than during the Baseline.
# Joy is zero inflated (most viewers show no Joy at Baseline), so the primary test is the Wilcoxon
# signed rank test; the paired t test and d_z are reported beside it. The two-tailed test is used.
cat("---- 4. H1: Joy Percent of time present, Commercial versus Baseline (paired, default threshold 50) ----\n")
jw <- joy_wide(fea_c)
res_h1 <- h1_test(jw$Baseline, jw$Commercial, "Joy Percent of time present (all kept respondents)")
cat(sprintf("Recovery (descriptive, 15 s stimulus): M = %.2f %%, SD = %.2f, Mdn = %.2f; viewers with any Joy: %d of %d\n\n",
            mean(jw$Recovery), sd(jw$Recovery), median(jw$Recovery), sum(jw$Recovery > 0), nrow(jw)))

# ---- 4b. Sensitivity: the same test at thresholds of 25 and 75 --------------
# The notebook was run again at a batch threshold of 25 and of 75 (files ..._threshold25.csv and
# ..._threshold75.csv). A lower threshold counts weaker and longer expression as present; a higher
# one counts only strong expression.
cat("---- 4b. H1 sensitivity: Joy Percent of time present at thresholds of 25 and 75 ----\n")
jw25 <- joy_wide(fea25_c); jw75 <- joy_wide(fea75_c)
stopifnot(identical(jw$respondent, jw25$respondent), identical(jw$respondent, jw75$respondent))
res_h1_25 <- h1_test(jw25$Baseline, jw25$Commercial, "Threshold 25 (more permissive)")
res_h1_75 <- h1_test(jw75$Baseline, jw75$Commercial, "Threshold 75 (stricter)")
sens <- tibble(threshold = c(25, 50, 75),
               m_base = c(res_h1_25$m_b, res_h1$m_b, res_h1_75$m_b), m_comm = c(res_h1_25$m_c, res_h1$m_c, res_h1_75$m_c),
               any_base = c(res_h1_25$b_any, res_h1$b_any, res_h1_75$b_any), any_comm = c(res_h1_25$c_any, res_h1$c_any, res_h1_75$c_any),
               mean_diff = c(res_h1_25$diff, res_h1$diff, res_h1_75$diff),
               V = c(res_h1_25$V, res_h1$V, res_h1_75$V), p_wilcoxon = c(res_h1_25$p_w, res_h1$p_w, res_h1_75$p_w),
               t = c(res_h1_25$t, res_h1$t, res_h1_75$t), p_t = c(res_h1_25$p, res_h1$p, res_h1_75$p),
               dz = c(res_h1_25$dz, res_h1$dz, res_h1_75$dz), r_rb = c(res_h1_25$r_rb, res_h1$r_rb, res_h1_75$r_rb))
cat("Summary across thresholds (Commercial minus Baseline):\n")
print(as.data.frame(sens %>% mutate(across(c(m_base, m_comm, mean_diff, t, dz, r_rb), ~ round(.x, 2)),
                                    p_wilcoxon = signif(p_wilcoxon, 3), p_t = signif(p_t, 3))), row.names = FALSE)
cat(sprintf("Ratio of the Commercial mean to the threshold 50 value: threshold 25 = %.2f, threshold 75 = %.2f\n\n",
            res_h1_25$m_c / res_h1$m_c, res_h1_75$m_c / res_h1$m_c))

# ---- 5. H2: Joy across the six bins -------------------------------------------
# H2: Joy Percent of time present differs across the six 10 s bins of the commercial (the plan is a
# concentration in the last two bins). Model: pct ~ bin + (1 | respondent), with bin as a factor (Bin_01
# is the reference level in the coefficient table). The F test is the omnibus test of the bin factor.
cat("---- 5. H2: Joy Percent of time present across the six bins ----\n")
bins <- bins_all %>% mutate(interval = factor(as.character(interval), levels = bin_levels)) %>% as.data.frame()
bins_w <- bins %>% select(respondent, interval, pct) %>% pivot_wider(names_from = interval, values_from = pct) %>% arrange(respondent)
mat <- as.matrix(bins_w[, bin_levels]); rownames(mat) <- bins_w$respondent
n_h2 <- nrow(mat)

# 5a. Proportion of viewers with Joy present in each bin (the quantity the FEA thresholding
# Aggregation shows in the Aggregate Replay), the mean time percent, and the mean number of segments.
prop_tab <- bind_rows(lapply(bin_levels, function(b) {
  x <- sum(mat[, b] > 0); bt <- binom.test(x, n_h2)
  ci <- t.test(mat[, b])$conf.int
  tibble(bin = b, n = n_h2, n_joy = x, prop = x / n_h2, prop_lo = bt$conf.int[1], prop_hi = bt$conf.int[2],
         mean_pct = mean(mat[, b]), sd_pct = sd(mat[, b]), mean_lo = ci[1], mean_hi = ci[2],
         mean_seg = mean(bins$nseg[bins$interval == b]))
}))
cat("5a. Viewers with Joy present per bin (Percent of time present above 0) and mean time percent:\n")
print(as.data.frame(prop_tab %>% mutate(prop = round(100 * prop, 1), prop_lo = round(100 * prop_lo, 1), prop_hi = round(100 * prop_hi, 1),
                                        across(c(mean_pct, sd_pct, mean_lo, mean_hi, mean_seg), ~ round(.x, 2)))), row.names = FALSE)
cat("(prop, prop_lo, prop_hi are percentages of viewers; the interval is the exact Clopper Pearson 95% CI.)\n")
top_prop <- prop_tab$bin[which.max(prop_tab$prop)]; top_mean <- prop_tab$bin[which.max(prop_tab$mean_pct)]
cat(sprintf("Highest proportion of viewers with Joy: %s (%.1f%%); highest mean time percent: %s (%.2f %%)\n\n",
            top_prop, 100 * max(prop_tab$prop), top_mean, max(prop_tab$mean_pct)))

# 5b. Linear mixed model
cat("5b. Mixed model: pct ~ bin + (1 | respondent)\n")
mm <- lmerTest::lmer(pct ~ interval + (1 | respondent), data = bins, REML = TRUE)
print(summary(mm, correlation = FALSE))
an <- anova(mm)
cat("\nType III test of the bin factor (Satterthwaite degrees of freedom):\n"); print(an)
f_bin <- an$`F value`; df1 <- an$NumDF; df2 <- an$DenDF; p_bin <- an$`Pr(>F)`
cat(sprintf("Bin factor: F(%d, %.0f) = %.2f, p = %s\n", df1, df2, f_bin, pf(p_bin)))
vc <- as.data.frame(VarCorr(mm))
var_resp <- vc$vcov[vc$grp == "respondent"]; var_res <- vc$vcov[vc$grp == "Residual"]
icc_adj <- var_resp / (var_resp + var_res)
mm0 <- lme4::lmer(pct ~ 1 + (1 | respondent), data = bins, REML = TRUE)
vc0 <- as.data.frame(VarCorr(mm0)); icc_null <- vc0$vcov[vc0$grp == "respondent"] / sum(vc0$vcov)
cat(sprintf("Respondent variance = %.2f (SD %.2f), residual variance = %.2f (SD %.2f)\n", var_resp, sqrt(var_resp), var_res, sqrt(var_res)))
cat(sprintf("ICC (adjusted, from the fitted model) = %.3f; ICC (unconditional, intercept only model) = %.3f\n", icc_adj, icc_null))

# Planned descriptive contrasts: the late bins against the mean of Bin_01 to Bin_04. Coefficient order:
# (Intercept), Bin_02, Bin_03, Bin_04, Bin_05, Bin_06 (treatment coding, Bin_01 is the reference).
L5 <- c(0, -1/4, -1/4, -1/4, 1, 0); L6 <- c(0, -1/4, -1/4, -1/4, 0, 1)
c5 <- lmerTest::contest1D(mm, L5, confint = TRUE); c6 <- lmerTest::contest1D(mm, L6, confint = TRUE)
p_holm <- p.adjust(c(c5$`Pr(>|t|)`, c6$`Pr(>|t|)`), method = "holm")
cat("\nContrasts against the mean of Bin_01 to Bin_04 (Satterthwaite df; Holm adjustment over the two contrasts):\n")
cat(sprintf("  Bin_05 minus mean(Bin_01..Bin_04) = %.2f percentage points, SE = %.2f, df = %.1f, t = %.2f, p = %s, Holm p = %s, 95%% CI [%.2f, %.2f]\n",
            c5$Estimate, c5$`Std. Error`, c5$df, c5$`t value`, pf(c5$`Pr(>|t|)`), pf(p_holm[1]), c5$lower, c5$upper))
cat(sprintf("  Bin_06 minus mean(Bin_01..Bin_04) = %.2f percentage points, SE = %.2f, df = %.1f, t = %.2f, p = %s, Holm p = %s, 95%% CI [%.2f, %.2f]\n\n",
            c6$Estimate, c6$`Std. Error`, c6$df, c6$`t value`, pf(c6$`Pr(>|t|)`), pf(p_holm[2]), c6$lower, c6$upper))

# 5c. Friedman test (nonparametric check)
fr <- friedman.test(mat)
kw <- unname(fr$statistic) / (n_h2 * (ncol(mat) - 1))
cat("5c. Friedman rank sum test across the six bins (the nonparametric check):\n")
cat(sprintf("  Friedman chi-squared(%d) = %.2f, p = %s; Kendall's W = %.3f (n = %d respondents)\n", as.integer(fr$parameter),
            fr$statistic, pf(fr$p.value), kw, n_h2))
rank_sums <- colSums(t(apply(mat, 1, rank)))
cat("  Rank sums by bin:", paste(sprintf("%s = %.1f", bin_levels, rank_sums), collapse = "; "), "\n")

# 5d. Robustness: the same model on the square root of the percent (reduces the right skew)
mm_sq <- lmerTest::lmer(sqrt(pct) ~ interval + (1 | respondent), data = bins, REML = TRUE)
an_sq <- anova(mm_sq)
cat(sprintf("\n5d. Robustness: model on sqrt(Percent of time present): F(%d, %.0f) = %.2f, p = %s\n\n",
            an_sq$NumDF, an_sq$DenDF, an_sq$`F value`, pf(an_sq$`Pr(>F)`)))

# ---- 6. H3: Positive Valence during the commercial and ad liking -------------
# H3: viewers who show more Positive Valence during the commercial like the ad more. Positive Valence is the
# Valence channel above +50. Ad_liking_1to7 is a whole number rating, so Spearman's rho is reported beside
# Pearson's r. The Spearman interval is the Bonett and Wright (2000) Fisher type interval.
cat("---- 6. H3: Positive Valence Percent of time present (Commercial) and Ad_liking_1to7 ----\n")
h3 <- fea_c %>% filter(expr == "Positive Valence", interval == "Commercial") %>% select(respondent, pv = pct) %>%
  inner_join(survey_c %>% select(respondent, liking, attitude, share), by = "respondent") %>% arrange(respondent)
n_h3 <- nrow(h3)
cat(sprintf("Positive Valence during the commercial: M = %.2f %%, SD = %.2f, Mdn = %.2f, viewers with any: %d of %d\n",
            mean(h3$pv), sd(h3$pv), median(h3$pv), sum(h3$pv > 0), n_h3))
cat(sprintf("Ad_liking_1to7: M = %.2f, SD = %.2f, range %d to %d (n = %d); number of distinct values = %d\n",
            mean(h3$liking), sd(h3$liking), min(h3$liking), max(h3$liking), n_h3, n_distinct(h3$liking)))
ct_p <- cor.test(h3$pv, h3$liking, method = "pearson")
ct_s <- suppressWarnings(cor.test(h3$pv, h3$liking, method = "spearman", exact = FALSE))
rho <- unname(ct_s$estimate)
bw_se <- sqrt((1 + rho^2 / 2) / (n_h3 - 3))
rho_lo <- tanh(atanh(rho) - qnorm(0.975) * bw_se); rho_hi <- tanh(atanh(rho) + qnorm(0.975) * bw_se)
cat(sprintf("Pearson r(%d) = %.2f, 95%% CI [%.2f, %.2f], t = %.2f, p = %s\n", as.integer(ct_p$parameter), ct_p$estimate,
            ct_p$conf.int[1], ct_p$conf.int[2], ct_p$statistic, pf(ct_p$p.value)))
cat(sprintf("Spearman rho = %.2f, 95%% CI [%.2f, %.2f] (Bonett and Wright), t(%d) = %.2f, p = %s (t approximation, ties present)\n",
            rho, rho_lo, rho_hi, n_h3 - 2, rho * sqrt((n_h3 - 2) / (1 - rho^2)), pf(ct_s$p.value)))
lm3 <- lm(pv ~ liking, data = h3); cf3 <- summary(lm3)$coefficients; ci3 <- confint(lm3)
cat(sprintf("Least squares line: Positive Valence %% = %.2f + %.2f x liking; slope SE = %.2f, 95%% CI [%.2f, %.2f]; R squared = %.2f\n",
            cf3[1, 1], cf3[2, 1], cf3[2, 2], ci3[2, 1], ci3[2, 2], summary(lm3)$r.squared))
sw_pv <- shapiro.test(h3$pv); sw_lk <- shapiro.test(h3$liking)
cat(sprintf("Shapiro Wilk: Positive Valence %% W = %.3f, p = %s; liking W = %.3f, p = %s\n",
            sw_pv$statistic, pf(sw_pv$p.value), sw_lk$statistic, pf(sw_lk$p.value)))
cat(sprintf("Exploratory: Joy Percent of time present (Commercial) with liking: r = %.2f\n\n",
            cor(jw$Commercial[match(h3$respondent, jw$respondent)], h3$liking)))

# ---- 7. Other expressions by bin (descriptive) --------------------------------
cat("---- 7. Other expressions by bin (descriptive, kept respondents, default thresholds) ----\n")
oth <- desc %>% filter(interval_type == "Annotation", expression %in% c("Surprise", "Brow Furrow", "Positive Valence", "Negative Valence")) %>%
  select(expression, interval, mean_pct) %>% pivot_wider(names_from = interval, values_from = mean_pct)
cat("Mean Percent of time present by bin:\n"); print(as.data.frame(oth), row.names = FALSE)
sur_w <- fea_c %>% filter(expr == "Surprise", itype == "Annotation") %>% select(respondent, interval, pct) %>%
  mutate(interval = factor(as.character(interval), levels = bin_levels)) %>% pivot_wider(names_from = interval, values_from = pct)
sur_p <- sapply(bin_levels, function(b) mean(sur_w[[b]] > 0))
cat("Viewers with Surprise present per bin (%):", paste(sprintf("%s = %.1f", bin_levels, 100 * sur_p), collapse = "; "), "\n")
sur_means <- unlist(oth[oth$expression == "Surprise", bin_levels])
cat(sprintf("Surprise peaks in %s (mean %.2f %%); the next highest bin is %.2f %%\n",
            names(which.max(sur_means)), max(sur_means), sort(sur_means, decreasing = TRUE)[2]))
brw_means <- unlist(oth[oth$expression == "Brow Furrow", bin_levels])
cat(sprintf("Brow Furrow bin means range from %.2f to %.2f %% (flat)\n", min(brw_means), max(brw_means)))
eng_bin <- desc %>% filter(expression == "Engagement", interval_type == "Annotation") %>% pull(mean_raw_score)
cat("Engagement mean raw score by bin:", paste(sprintf("%.2f", eng_bin), collapse = ", "), "\n\n")

# ---- 8. Assumption checks ----------------------------------------------------
cat("---- 8. Assumption checks ----\n")
skew <- function(x) mean((x - mean(x))^3) / (mean((x - mean(x))^2))^1.5
cat(sprintf("Joy Percent of time present is zero inflated and right skewed: Baseline zeros %d of %d, skewness %.2f; Commercial zeros %d of %d, skewness %.2f\n",
            sum(jw$Baseline == 0), nrow(jw), skew(jw$Baseline), sum(jw$Commercial == 0), nrow(jw), skew(jw$Commercial)))
cat(sprintf("Across the six bins, %d of %d Joy values are exactly 0 (%.1f%%)\n",
            sum(bins$pct == 0), nrow(bins), 100 * mean(bins$pct == 0)))
cat(sprintf("Shapiro Wilk on the H1 differences (Commercial minus Baseline): W = %.3f, p = %s\n",
            res_h1$shapiro_w, pf(res_h1$shapiro_p)))
re_int <- ranef(mm)$respondent[, 1]
sw_res <- shapiro.test(resid(mm)); sw_re <- shapiro.test(re_int); sw_sq <- shapiro.test(resid(mm_sq))
cat(sprintf("Shapiro Wilk on the mixed model residuals: W = %.3f, p = %s\n", sw_res$statistic, pf(sw_res$p.value)))
cat(sprintf("Shapiro Wilk on the respondent random intercepts: W = %.3f, p = %s\n", sw_re$statistic, pf(sw_re$p.value)))
cat(sprintf("Shapiro Wilk on the residuals of the sqrt(percent) model: W = %.3f, p = %s\n", sw_sq$statistic, pf(sw_sq$p.value)))
cat(sprintf("Residual SD by bin (largest / smallest): %.2f\n",
            max(tapply(resid(mm), bins$interval, sd)) / min(tapply(resid(mm), bins$interval, sd))))
cat("The residuals are not normal and their spread grows with the bin mean, which is why the Friedman test and the sqrt model are reported beside the F test.\n")
cat("H3: Pearson's r assumes a roughly linear relation and no extreme points; see figures/SIMULATED_fig3_valence_liking.png.\n")

png(file.path(fig_dir, "SIMULATED_assumption_checks.png"), width = 1400, height = 1000, res = 150)
par(mfrow = c(2, 3), mar = c(4, 4, 3, 1))
qqnorm(res_h1$dif, main = "H1 differences (Joy %): normal QQ", col = col_navy, pch = 16); qqline(res_h1$dif, col = "#444444")
hist(jw$Commercial, breaks = seq(0, ceiling(max(jw$Commercial) / 5) * 5, by = 5), col = col_tint, border = "white",
     main = "Joy % during the commercial", xlab = "Percent of time present", ylab = "Viewers")
hist(jw$Baseline, breaks = seq(0, ceiling(max(c(jw$Baseline, 5)) / 5) * 5, by = 5), col = paste0(col_gray, "99"), border = "white", add = FALSE,
     main = "Joy % at Baseline (zero inflated)", xlab = "Percent of time present", ylab = "Viewers")
plot(fitted(mm), resid(mm), pch = 16, col = "#1F386488", xlab = "Fitted Joy % (mixed model)", ylab = "Residual",
     main = "Mixed model: residuals vs fitted"); abline(h = 0, col = col_accent)
qqnorm(resid(mm), main = "Mixed model: residual QQ", pch = 16, col = "#1F386488"); qqline(resid(mm), col = col_accent)
qqnorm(re_int, main = "Mixed model: respondent intercepts QQ", pch = 16, col = "#1F386488"); qqline(re_int, col = col_accent)
invisible(dev.off())
cat("saved figure: figures/SIMULATED_assumption_checks.png\n")
cat("Reading the plots: points near the line = roughly normal. A curved QQ line and a fan shape in\n",
    "residuals vs fitted = right skew and variance that grows with the mean (use the rank based\n",
    "tests or the sqrt model). The Baseline histogram shows the spike at zero.\n\n")

# ---- 9. Figures --------------------------------------------------------------
ci95 <- function(x) { x <- x[!is.na(x)]; qt(0.975, length(x) - 1) * sd(x) / sqrt(length(x)) }

# Figure 1: Joy by stimulus. A gray line per respondent connects Baseline, Commercial, and Recovery; the
