  mutate(stim = factor(stim, levels = stim_levels), pos = as.integer(stim)) %>%
  group_by(respondent) %>% mutate(off = runif(1, -0.13, 0.13)) %>% ungroup() %>% mutate(x = pos + off)
f1_mean <- f1_long %>% group_by(stim, pos) %>% summarise(mean = mean(y), ci = ci95(y), n_any = sum(y > 0), .groups = "drop") %>%
  mutate(xo = pos + 0.3)
lab1 <- sprintf("%s\n(%s)\nJoy in %d of %d", c("Baseline", "Commercial", "Recovery"), c("60 s", "60 s", "15 s"),
                f1_mean$n_any, nrow(jw))
fig1 <- ggplot() +
  geom_line(data = f1_long, aes(x = x, y = y, group = respondent), color = "#B8B8B8", linewidth = 0.45) +
