  geom_errorbar(data = f1_mean, aes(x = xo, ymin = pmax(mean - ci, 0), ymax = mean + ci), width = 0.07, linewidth = 0.9, color = col_accent) +
  geom_point(data = f1_mean, aes(x = xo, y = mean), size = 4, color = col_accent) +
  geom_text(data = f1_mean, aes(x = xo, y = mean, label = sprintf("M = %.1f", mean)), hjust = -0.35, size = 3.8, color = "#333333") +
  scale_color_manual(values = c(Baseline = col_gray, Commercial = col_navy, Recovery = col_gray), guide = "none") +
