  labs(title = "Joy: percent of stimulus time present (default threshold 50)",
       subtitle = sprintf("Each line is one viewer; mean with 95%% CI in accent.\nCommercial vs Baseline: Wilcoxon V = %.0f, %s; paired t(%d) = %.2f, %s; d_z = %.2f",
                          res_h1$V, fp(res_h1$p_w), as.integer(res_h1$df), res_h1$t, fp(res_h1$p), res_h1$dz),
       x = NULL, y = "Percent of stimulus time with Joy present (%)",
       caption = sprintf("SIMULATED teaching data (make_simulated_data.py). Not real viewers. n = %d kept respondents (Data quality of at least %d%%).\nMost viewers show no Joy at Baseline, so many points sit at zero.", nrow(jw), dq_rule)) +
  theme_fea() + theme(legend.position = "none")
