# ---- Summary tables of the tests ----------------------------------------------
add_res <- function(hypothesis, analysis, quantity, estimate = NA, ci_low = NA, ci_high = NA, statistic = NA, df = NA, p = NA, n = NA) {
  tibble(hypothesis = hypothesis, analysis = analysis, quantity = quantity, estimate = estimate, ci_low = ci_low,
         ci_high = ci_high, statistic = statistic, df = df, p = p, n = n)
}
h1_rows <- function(r, tag) {
  bind_rows(
    add_res(tag, "Descriptive", "Baseline mean Percent of time present", r$m_b, n = r$n),
    add_res(tag, "Descriptive", "Commercial mean Percent of time present", r$m_c, n = r$n),
    add_res(tag, "Descriptive", "Viewers with any Joy, Baseline", r$b_any, n = r$n),
    add_res(tag, "Descriptive", "Viewers with any Joy, Commercial", r$c_any, n = r$n),
    add_res(tag, "Exact McNemar test", "Joy present only at Baseline versus only during the Commercial", r$disc_c - r$disc_b, p = r$mcn_p, n = r$n),
    add_res(tag, "Wilcoxon signed rank (primary)", "V (sum of positive ranks)", statistic = r$V, p = r$p_w, n = r$n_nz),
    add_res(tag, "Wilcoxon signed rank (primary)", "Matched pairs rank biserial correlation", r$r_rb, n = r$n_nz),
    add_res(tag, "Wilcoxon signed rank (primary)", "Hodges-Lehmann median difference", r$hl, r$hl_lo, r$hl_hi, n = r$n_nz),
    add_res(tag, "Paired t test", "Mean difference (Commercial minus Baseline)", r$diff, r$ci_lo, r$ci_hi, r$t, r$df, r$p, r$n),
    add_res(tag, "Paired t test", "Cohen's d_z", r$dz, r$dz_lo, r$dz_hi, n = r$n))
}
tests <- bind_rows(
  h1_rows(res_h1, "H1 threshold 50"),
  h1_rows(res_h1_25, "H1 sensitivity threshold 25"),
  h1_rows(res_h1_75, "H1 sensitivity threshold 75"),
  add_res("H2", "Mixed model pct ~ bin + (1 | respondent)", "Bin factor F test", statistic = f_bin, df = df2, p = p_bin, n = n_h2),
  add_res("H2", "Mixed model pct ~ bin + (1 | respondent)", "ICC adjusted", icc_adj, n = n_h2),
  add_res("H2", "Contrast (Satterthwaite)", "Bin_05 minus mean(Bin_01..Bin_04)", c5$Estimate, c5$lower, c5$upper, c5$`t value`, c5$df, c5$`Pr(>|t|)`, n_h2),
  add_res("H2", "Contrast (Satterthwaite)", "Bin_06 minus mean(Bin_01..Bin_04)", c6$Estimate, c6$lower, c6$upper, c6$`t value`, c6$df, c6$`Pr(>|t|)`, n_h2),
  add_res("H2", "Mixed model on sqrt(percent)", "Bin factor F test", statistic = an_sq$`F value`, df = an_sq$DenDF, p = an_sq$`Pr(>F)`, n = n_h2),
  add_res("H2", "Friedman test", "Chi-squared", statistic = unname(fr$statistic), df = unname(fr$parameter), p = fr$p.value, n = n_h2),
  add_res("H2", "Friedman test", "Kendall's W", kw, n = n_h2),
  bind_rows(lapply(seq_len(nrow(prop_tab)), function(i) add_res("H2", "Proportion of viewers with Joy present",
            paste0(prop_tab$bin[i], ": proportion with Joy present"), prop_tab$prop[i], prop_tab$prop_lo[i], prop_tab$prop_hi[i], n = n_h2))),
  bind_rows(lapply(seq_len(nrow(prop_tab)), function(i) add_res("H2", "Mean Percent of time present",
            paste0(prop_tab$bin[i], ": mean Joy percent"), prop_tab$mean_pct[i], prop_tab$mean_lo[i], prop_tab$mean_hi[i], n = n_h2))),
  add_res("H3", "Pearson", "r (Positive Valence % with Ad_liking_1to7)", unname(ct_p$estimate), ct_p$conf.int[1], ct_p$conf.int[2],
          unname(ct_p$statistic), unname(ct_p$parameter), ct_p$p.value, n_h3),
  add_res("H3", "Spearman", "rho (Positive Valence % with Ad_liking_1to7)", rho, rho_lo, rho_hi,
          rho * sqrt((n_h3 - 2) / (1 - rho^2)), n_h3 - 2, ct_s$p.value, n_h3),
  add_res("H3", "Least squares line", "Slope (percentage points per liking point)", cf3[2, 1], ci3[2, 1], ci3[2, 2],
          cf3[2, 3], lm3$df.residual, cf3[2, 4], n_h3)) %>%
  mutate(across(where(is.numeric) & !any_of("p"), ~ round(.x, 6)), p = signif(p, 4))
